// express a configurable multi-hop chain or a guaranteed limit overflow.
func TestDefaultApiClient_ConcurrentRedirectCountIsPerRequest(t *testing.T) {
	t.Parallel()

	// /chain/0 terminates with 200; /chain/N (N>0) redirects to /chain/N-1.
	// A request to /chain/N therefore performs exactly N redirect hops.
	var server *httptest.Server
	server = httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		n, err := strconv.Atoi(strings.TrimPrefix(r.URL.Path, "/chain/"))
		if err != nil || n <= 0 {
			w.WriteHeader(http.StatusOK)
			return
		}
		w.Header().Set("Location", fmt.Sprintf("%s/chain/%d", server.URL, n-1))
		w.WriteHeader(http.StatusFound)
	}))
	defer server.Close()

	const maxRedirects = 5
	// One shared client across every concurrent request — the crux of the
	// test. If redirect state lived on the client/transport the deep
	// requests' hops would corrupt the shallow ones (or vice versa).
	transport := NewTransportOptionsBuilder().
		FollowRedirects(true).
		MaxRedirects(maxRedirects).
		Build()
	client := NewDefaultApiClient(transport)

	// Interleave many shallow (1-hop, must succeed) and deep (20-hop, must
	// hit the limit) requests so their redirect handling overlaps in time.
	type expectation struct {
		hops    int
		wantErr bool // true when hops > maxRedirects
	}
	var cases []expectation
	for i := 0; i < 12; i++ {
		cases = append(cases,
			expectation{hops: 1, wantErr: false},
			expectation{hops: 20, wantErr: true},
		)
	}

	var wg sync.WaitGroup
	errs := make([]error, len(cases))
	codes := make([]int, len(cases))
	for i, c := range cases {
		wg.Add(1)
		go func(idx int, ex expectation) {
			defer wg.Done()
			resp, err := client.SendRequest(
				"GET",
				fmt.Sprintf("%s/chain/%d", server.URL, ex.hops),
				map[string]string{}, nil,
			)
			errs[idx] = err
			if resp != nil {
				codes[idx] = resp.StatusCode
			}
		}(i, c)
	}
	wg.Wait()

	for i, c := range cases {
		if c.wantErr {
			// A deep request must fail on its OWN over-limit chain — and the
			// refusal must name the limit, not be a spurious error inherited
			// from a concurrent request.
			if errs[i] == nil {
				t.Errorf("case %d (%d hops): expected too-many-redirects error, got nil (status %d)", i, c.hops, codes[i])
				continue
			}
			if !strings.Contains(errs[i].Error(), strconv.Itoa(maxRedirects)) {
				t.Errorf("case %d (%d hops): expected limit error mentioning %d, got %q", i, c.hops, maxRedirects, errs[i].Error())
			}
		} else {
			// A shallow request stays well under the limit and must succeed —
			// it must NOT be failed by a concurrent deep request's overflow.
			if errs[i] != nil {
				t.Errorf("case %d (%d hops): expected success, got error %q", i, c.hops, errs[i].Error())
				continue
			}
			if codes[i] != 200 {
				t.Errorf("case %d (%d hops): expected status 200, got %d", i, c.hops, codes[i])
			}
		}
	}
}
